from pathlib import Path
import re

ROOT = Path(__file__).resolve().parents[1]
MAIN = ROOT / 'app/src/main/java/com/humbleman/visualiseur/MainActivity.java'
GRADLE = ROOT / 'app/build.gradle'

text = MAIN.read_text(encoding='utf-8')

# Keep the visualizer full-frame. Only opacity/strength is adjustable.
text = text.replace('            visualizerScale = 1.0f;\n', '            visualizerScale = 1.0f;\n', 1)

helper_anchor = '        private void drawLyricsAndText(Canvas c, int w, int h, long curMs) {'
helpers = '''        private int alphaFor(int baseAlpha, float intensity) {\n            float v = Math.max(0f, Math.min(1f, intensity));\n            return Math.max(0, Math.min(255, Math.round(baseAlpha * v)));\n        }\n\n        private int colorWithIntensity(int color, float intensity) {\n            return Color.argb(alphaFor(Color.alpha(color), intensity), Color.red(color), Color.green(color), Color.blue(color));\n        }\n\n'''
if 'private int alphaFor(int baseAlpha' not in text and helper_anchor in text:
    text = text.replace(helper_anchor, helpers + helper_anchor, 1)

rs = text.find('            // Render visualizer styles')
re_end = text.find('            paint.clearShadowLayer();', rs) if rs >= 0 else -1
if rs >= 0 and re_end > rs:
    section = text[rs:re_end]
    section = re.sub(r'paint\.setAlpha\(([^;]+)\);', r'paint.setAlpha(alphaFor((int)(\1), visualizerIntensity));', section)
    text = text[:rs] + section + text[re_end:]

ls = text.find('        private void drawLyricsAndText(Canvas c, int w, int h, long curMs) {')
le = text.find('        private void drawFittedCentered', ls) if ls >= 0 else -1
if ls >= 0 and le > ls:
    lyr = text[ls:le]
    lyr = lyr.replace('int alpha = (offset == 1 || offset == -1) ? 140 : 60;', 'int alpha = alphaFor((offset == 1 || offset == -1) ? 140 : 60, lyricsIntensity);')
    lyr = lyr.replace('textPaint.setShadowLayer(dp(12), 0, 0, Color.parseColor(activeColor));', 'textPaint.setShadowLayer(dp(12), 0, 0, colorWithIntensity(Color.parseColor(activeColor), lyricsIntensity));')
    lyr = lyr.replace('textPaint.setShadowLayer(dp(10), 0, 0, Color.parseColor(activeColor));', 'textPaint.setShadowLayer(dp(10), 0, 0, colorWithIntensity(Color.parseColor(activeColor), lyricsIntensity));')
    text = text[:ls] + lyr + text[le:]

trans_start = text.find('        static Transcript transcribe(String rawKey, File file, String mime, String language) throws Exception {')
trans_end = text.find('        static List<LyricLine> translateLyrics', trans_start) if trans_start >= 0 else -1
if trans_start < 0 or trans_end < 0:
    raise SystemExit('Groq transcribe method not found')

new_transcribe = '''        static Transcript transcribe(String rawKey, File file, String mime, String language) throws Exception {\n            final String key = rawKey == null ? "" : rawKey.trim();\n            if (key.isEmpty()) throw new Exception("Clé API Groq manquante.");\n            if (file == null || !file.exists()) throw new Exception("Fichier audio introuvable.");\n            if (file.length() > 25L * 1024L * 1024L) throw new Exception("Audio > 25 MB. Utilisez une version compressée ou découpée.");\n\n            String[] models = {"whisper-large-v3", "whisper-large-v3-turbo"};\n            Transcript best = null;\n            Exception last = null;\n            double bestScore = -1.0;\n\n            for (int modelIndex = 0; modelIndex < models.length; modelIndex++) {\n                String model = models[modelIndex];\n                try {\n                    String boundary = "----VA" + System.nanoTime();\n                    HttpURLConnection c = (HttpURLConnection) new URL(TRANS).openConnection();\n                    c.setConnectTimeout(30000);\n                    c.setReadTimeout(240000);\n                    c.setDoOutput(true);\n                    c.setRequestMethod("POST");\n                    c.setRequestProperty("Authorization", "Bearer " + key);\n                    c.setRequestProperty("Content-Type", "multipart/form-data; boundary=" + boundary);\n                    try (OutputStream out = c.getOutputStream()) {\n                        field(out, boundary, "model", model);\n                        if (language != null && !language.isEmpty()) field(out, boundary, "language", language);\n                        field(out, boundary, "prompt", "Transcris fidèlement des paroles chantées. N'omets aucun passage audible et conserve les mots dans leur ordre exact.");\n                        field(out, boundary, "temperature", "0.0");\n                        field(out, boundary, "response_format", "verbose_json");\n                        field(out, boundary, "timestamp_granularities[]", "segment");\n                        field(out, boundary, "timestamp_granularities[]", "word");\n                        part(out, boundary, "file", file.getName(), mime, new FileInputStream(file));\n                        out.write(("--" + boundary + "--\\r\\n").getBytes(StandardCharsets.UTF_8));\n                    }\n\n                    String raw = read(c);\n                    ensure(c, raw);\n                    JSONObject json = new JSONObject(raw);\n                    String fullText = json.optString("text", "").replaceAll("\\\\s+", " ").trim();\n                    ArrayList<LyricLine> segmentLines = new ArrayList<>();\n                    JSONArray segments = json.optJSONArray("segments");\n                    if (segments != null) {\n                        for (int i = 0; i < segments.length(); i++) {\n                            JSONObject seg = segments.getJSONObject(i);\n                            long start = Math.max(0L, Math.round(seg.optDouble("start", 0.0) * 1000.0));\n                            long end = Math.max(start + 300L, Math.round(seg.optDouble("end", 0.0) * 1000.0));\n                            String value = seg.optString("text", "").replaceAll("\\\\s+", " ").trim();\n                            if (!value.isEmpty()) segmentLines.add(new LyricLine(start, end, value));\n                        }\n                    }\n\n                    ArrayList<LyricLine> wordLines = new ArrayList<>();\n                    JSONArray words = json.optJSONArray("words");\n                    if (words != null) {\n                        StringBuilder line = new StringBuilder();\n                        long lineStart = -1L;\n                        long lineEnd = -1L;\n                        for (int i = 0; i < words.length(); i++) {\n                            JSONObject w = words.getJSONObject(i);\n                            long ws = Math.max(0L, Math.round(w.optDouble("start", 0.0) * 1000.0));\n                            long we = Math.max(ws + 120L, Math.round(w.optDouble("end", 0.0) * 1000.0));\n                            String value = w.optString("word", "").trim();\n                            if (value.isEmpty()) continue;\n                            if (line.length() == 0) lineStart = ws;\n                            if (line.length() > 0) line.append(' ');\n                            line.append(value);\n                            lineEnd = we;\n                            boolean punctuationBreak = value.matches(".*[.!?;,:]$");\n                            boolean sizeBreak = line.length() >= 76;\n                            boolean timeBreak = lineStart >= 0 && lineEnd - lineStart >= 4200L;\n                            if (punctuationBreak || sizeBreak || timeBreak) {\n                                wordLines.add(new LyricLine(lineStart, Math.max(lineStart + 300L, lineEnd), line.toString().trim()));\n                                line.setLength(0);\n                                lineStart = -1L;\n                                lineEnd = -1L;\n                            }\n                        }\n                        if (line.length() > 0 && lineStart >= 0) {\n                            wordLines.add(new LyricLine(lineStart, Math.max(lineStart + 300L, lineEnd), line.toString().trim()));\n                        }\n                    }\n\n                    ArrayList<LyricLine> chosen = !wordLines.isEmpty() ? wordLines : segmentLines;\n                    String chosenText = joinLyricText(chosen);\n                    if (chosen.isEmpty() && !segmentLines.isEmpty()) {\n                        chosen = segmentLines;\n                        chosenText = joinLyricText(chosen);\n                    }\n                    if (chosen.isEmpty() && !fullText.isEmpty()) chosen.add(new LyricLine(0L, 10000L, fullText));\n                    Collections.sort(chosen, (x, y) -> Long.compare(x.startMs, y.startMs));\n\n                    long duration = Math.max(Math.round(json.optDouble("duration", 0.0) * 1000.0), chosen.isEmpty() ? 0L : chosen.get(chosen.size() - 1).endMs);\n                    long covered = 0L;\n                    long previousEnd = -1L;\n                    for (LyricLine l : chosen) {\n                        long s = Math.max(l.startMs, previousEnd < 0 ? l.startMs : previousEnd);\n                        long e = Math.max(l.endMs, s + 300L);\n                        covered += Math.max(0L, e - s);\n                        previousEnd = Math.max(previousEnd, e);\n                    }\n                    double coverage = duration > 0 ? Math.min(1.0, covered / (double) duration) : 0.0;\n                    double textMatch = fullText.isEmpty() ? 0.0 : Math.min(1.0, chosenText.length() / (double) fullText.length());\n                    double score = chosenText.length() + chosen.size() * 18.0 + coverage * 900.0 + textMatch * 500.0;\n                    if (modelIndex == 0) score += 120.0;\n\n                    Transcript candidate = new Transcript(fullText, chosen);\n                    if (score > bestScore) {\n                        bestScore = score;\n                        best = candidate;\n                    }\n\n                    if (modelIndex == 0 && coverage >= 0.85 && textMatch >= 0.90 && chosen.size() >= 3) break;\n                } catch (Exception e) {\n                    last = e;\n                    if (e.getMessage() != null && e.getMessage().contains("401")) throw e;\n                }\n            }\n\n            if (best != null && !best.lines.isEmpty()) return best;\n            if (last != null) throw last;\n            throw new Exception("Échec de la transcription Whisper.");\n        }\n\n        private static String joinLyricText(List<LyricLine> lines) {\n            if (lines == null || lines.isEmpty()) return "";\n            StringBuilder sb = new StringBuilder();\n            for (LyricLine line : lines) {\n                if (line == null || line.text == null || line.text.isEmpty()) continue;\n                if (sb.length() > 0) sb.append(' ');\n                sb.append(line.text);\n            }\n            return sb.toString().trim();\n        }\n\n'''
text = text[:trans_start] + new_transcribe + text[trans_end:]
text = text.replace('GroqClient.Transcript t = GroqClient.transcribe(k, audioFile, audioMime, "fr");', 'GroqClient.Transcript t = GroqClient.transcribe(k, audioFile, audioMime, "");', 1)

ranges = [(0x1F1E6,0x1F1FF),(0x1F300,0x1FAFF),(0x1FC00,0x1FFFF),(0xFE00,0xFE0F),(0x200D,0x200D),(0x20E3,0x20E3)]
for p in Path(ROOT / 'app/src/main/java').rglob('*.java'):
    s = p.read_text(encoding='utf-8')
    cleaned = ''.join(ch for ch in s if not any(a <= ord(ch) <= b for a,b in ranges))
    if cleaned != s:
        p.write_text(cleaned, encoding='utf-8')

gradle = GRADLE.read_text(encoding='utf-8')
gradle = re.sub(r'(?m)^\\s*versionCode\\s+\\d+\\s*$', '        versionCode 23', gradle, count=1)
gradle = re.sub(r'(?m)^\\s*versionName\\s+"[^"]+"\\s*$', '        versionName "2.8.1"', gradle, count=1)
GRADLE.write_text(gradle, encoding='utf-8')
MAIN.write_text(text, encoding='utf-8')
